window.createAdventureUI=function(api){
'use strict';
const F=window.Frontera,$=id=>document.getElementById(id),esc=api.escape;let category='',target=0,mapMode='local',shopMode='buy',miniKey='',mini=null,atlasGeneration=null,shopPlace='basic';
const money=n=>'₽ '+Math.round(n).toLocaleString('es-UY');
function itemCard(i,count,actions){return '<article class="itemcard"><img src="'+i.sprite+'" width="40" height="40" alt=""><div><b>'+esc(i.name)+'</b><small>'+F.itemCategories[i.category]+' · '+count+'</small><p>'+esc(i.description)+'</p>'+actions+'</div></article>'}
function moveChoices(c){$('bagMove').innerHTML=c.progression.learned.map(k=>'<option value="'+k+'">'+esc(window.MOVE_DATA[k].name)+'</option>').join('');if(!c.progression.learned.includes($('bagMove').value))$('bagMove').value=c.progression.learned[0]}
function renderBag(){const s=F.ensureEconomy(api.state()),b=api.battle();target=F.clamp(target,0,s.team.length-1);const c=s.team[target];$('bagMoney').textContent=money(s.money);$('bagCards').textContent='Tarjetas del shopping: '+(Object.keys(s.shopping.cards).map(n=>F.SHOPPING_CARDS[n].name).join(' · ')||'Aún no encontraste ninguna.');$('bagTarget').innerHTML=s.team.map((c,i)=>'<option value="'+i+'">'+F.DATA[c.id].name+' · Nv. '+c.level+' · '+Math.ceil(b?b.roster[i].hp:F.creatureHealth(c).hp)+' / '+F.maxHP(c)+' PS'+'</option>').join('');$('bagTarget').value=String(target);moveChoices(c);$('heldName').textContent=c.heldItem?F.ITEMS[c.heldItem].name:'Sin objeto equipado';$('unequipBtn').disabled=!!b||!c.heldItem;$('bagCategory').innerHTML='<option value="">Todas las categorías</option>'+Object.entries(F.itemCategories).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');$('bagCategory').value=category;const list=Object.values(F.ITEMS).filter(i=>F.itemCount(s,i.key)>0&&(!category||category===i.category));$('bagItems').innerHTML=list.length?list.map(i=>{const equipment=['held','berries'].includes(i.category),usable=['medicine','berries','travel','training','battle','key'].includes(i.category),medical=['heal','cleanse','energy','revive','buff'].includes(i.effect),disabled=medical&&!b&&!['heal','revive'].includes(i.effect)||!!b&&['travel','training','key'].includes(i.category);return itemCard(i,F.itemCount(s,i.key)+' en mochila',(usable?'<button class="secondary" data-useitem="'+i.key+'" '+(disabled?'disabled':'')+'>'+(disabled&&medical&&!b?'En combate':'Usar')+'</button>':'')+(equipment?'<button class="secondary" data-equipitem="'+i.key+'" '+(b?'disabled':'')+'>Equipar</button>':'')+(i.category==='evolution'?'<button class="secondary" data-evolveitem="'+i.key+'" '+(b?'disabled':'')+'>Evolucionar</button>':''))}).join(''):'<p>No tienes objetos de esta categoría.</p>';
for(const btn of document.querySelectorAll('[data-useitem]'))btn.onclick=()=>{const s=api.state(),r=F.useItem(s,btn.dataset.useitem,{battle:api.battle(),combat:window.Fight,index:target,moveKey:$('bagMove').value});if(!r.ok){api.toast(r.message);return}if(r.map){$('bagDialog').close();map();return}if(r.fish){const enc=F.fishingEncounter(s,r.fish);if(!enc){api.toast(s.fishingCooldown>0?'Espera antes de volver a pescar.':'Acércate al agua de una ruta para pescar.');return}$('bagDialog').close();api.save();api.encounter(enc);return}api.changed();renderBag();api.toast(r.message)};
for(const btn of document.querySelectorAll('[data-equipitem]'))btn.onclick=()=>{if(F.equipHeld(api.state(),target,btn.dataset.equipitem,api.battle())){api.changed();renderBag();api.toast('Objeto equipado.')}};
for(const btn of document.querySelectorAll('[data-evolveitem]'))btn.onclick=()=>{if(api.battle())return;api.state().active=target;$('bagDialog').close();api.evolve()};}
function bag(){if(api.battle()?.result)return;target=api.state().active;category='';renderBag();api.openDialog('bagDialog')}
function renderShop(){const s=api.state(),available=new Set(F.shopStock(s,shopPlace).map(i=>i.key)),mall=shopPlace==='mall';$('shopTitle').textContent=mall?'Shopping Rocío':'Tienda Pokémon';$('shopMoney').textContent=money(s.money);$('shopNote').textContent=shopMode==='buy'?(mall?'Plantas por tarjeta · '+Object.entries(F.SHOPPING_CARDS).map(([n,c])=>c.name+(s.shopping.cards[n]?' ✓':' · acceso cerrado')).join(' / ')+'. Las tarjetas se encuentran explorando; las medallas no compran acceso.':'Suministros básicos para viajar y entrenar. En Ciudad Rocío encontrarás el shopping con productos especializados.'):'La reventa vale menos que la compra. Los objetos clave y la Master Ball no se venden.';const list=shopMode==='buy'?F.shopCatalog(shopPlace):Object.values(F.ITEMS).filter(i=>F.itemCount(s,i.key)>0&&i.sell>0&&!i.keyItem&&!i.unique);$('shopItems').innerHTML=list.map(i=>itemCard(i,F.itemCount(s,i.key)+' en mochila',shopMode==='buy'?'<button class="secondary" data-buyitem="'+i.key+'" '+(!available.has(i.key)||s.money<i.price||i.keyItem&&F.itemCount(s,i.key)>0?'disabled':'')+'>'+(available.has(i.key)?'Comprar · '+money(i.price):F.SHOPPING_CARDS[F.shopItemTier(i)].name+' requerida')+'</button>':'<button class="secondary" data-sellitem="'+i.key+'">Vender 1 · '+money(i.sell)+'</button>')).join('')||'<p>No tienes objetos para vender.</p>';for(const b of document.querySelectorAll('[data-buyitem]'))b.onclick=()=>{if(api.battle())return;if(F.buyItem(s,b.dataset.buyitem,1,shopPlace)){api.changed();renderShop();api.toast('Compra realizada.')}};for(const b of document.querySelectorAll('[data-sellitem]'))b.onclick=()=>{if(api.battle())return;if(F.sellItem(s,b.dataset.sellitem)){api.changed();renderShop();api.toast('Objeto vendido.')}};$('shopBuyTab').classList.toggle('selected',shopMode==='buy');$('shopSellTab').classList.toggle('selected',shopMode==='sell')}
function shop(place='basic'){if(api.battle()||place==='mall'&&!F.isShoppingTown(api.state().mapId))return;shopPlace=place==='mall'?'mall':'basic';shopMode='buy';renderShop();api.openDialog('shopDialog')}
function discovered(s,x,y){return!!s.fog?.[s.mapId]?.[Math.floor(x/8)+','+Math.floor(y/8)]}
function drawLocal(ctx,s,w,h,miniature=false){const m=F.MAPS[s.mapId],b=m.bounds,scale=Math.min((w-18)/(b.right-b.left),(h-18)/(b.bottom-b.top)),ox=w/2,oy=h/2;ctx.fillStyle='#172c26';ctx.fillRect(0,0,w,h);for(let y=Math.floor(b.top/32);y<b.bottom/32;y++)for(let x=Math.floor(b.left/32);x<b.right/32;x++){if(!discovered(s,x,y))continue;const t=F.fieldTile?F.fieldTile(s,x,y):F.mapTile(m.id,x,y,s.seed),colors={water:'#4e8392',waterfall:'#a9d4d5',snow:'#c0d6d8',sand:'#b9a170',rock:'#7e8a80',grass:F.REGIONS[m.region].color,trail:'#c8ba8a',paved:'#c5c4a9',dungeon:'#7b8b81',wall:'#33443e','gym-floor':F.GYM_THEMES?.[m.region]?.floor,'gym-wall':F.GYM_THEMES?.[m.region]?.wall,'gym-gate':t.gateOpen?'#7ba26e':'#caa866',bridge:'#c9b17b',lava:'#bd7044',ice:'#83b6c3'};ctx.fillStyle=t.landmark?'#bca87b':t.obstacle?(t.obstacle==='cliff'?'#657b69':t.tree?'#385e48':'#6d806c'):colors[t.ground]||'#486e4c';ctx.fillRect(ox+x*32*scale,oy+y*32*scale,32*scale+.3,32*scale+.3)}const town=F.mapTown(m.id);if(town){for(const house of town.buildings){if(!discovered(s,Math.floor(house.x/32),Math.floor(house.y/32)))continue;ctx.fillStyle=house.id==='gym'?'#d8b46e':house.roof;ctx.fillRect(ox+house.x*scale,oy+house.y*scale,house.w*scale,house.h*scale)}}for(const exit of F.worldExits(s)){if(!discovered(s,Math.floor(exit.x/32),Math.floor(exit.y/32)))continue;const x=ox+exit.x*scale,y=oy+exit.y*scale;ctx.fillStyle=exit.beginner?'#a5e58b':'#e5d087';ctx.fillRect(x-3,y-3,6,6);if(!miniature){ctx.fillStyle='#f2eccd';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(exit.beginner?'ENTRENAR · '+F.mapLevels(s,exit.target).join('–'):exit.locked?'Frontera desconocida':F.MAPS[exit.target].name,F.clamp(x,90,w-90),F.clamp(y-9,12,h-12))}}for(const o of F.legendObjects?.(s)||[]){if(!discovered(s,Math.floor(o.x/32),Math.floor(o.y/32)))continue;ctx.fillStyle=o.locked?'#899680':o.color;const x=ox+o.x*scale,y=oy+o.y*scale;ctx.fillRect(x-3,y-3,6,6);if(!miniature){ctx.fillStyle='#efe8bd';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText(o.role==='shrine'?'Santuario':'Pista',F.clamp(x,30,w-30),F.clamp(y+12,12,h-12));}}for(const o of F.cardObjects(s)){if(!discovered(s,Math.floor(o.x/32),Math.floor(o.y/32)))continue;ctx.fillStyle=o.color;ctx.fillRect(ox+o.x*scale-3,oy+o.y*scale-2,6,4)}const x=ox+s.player.x*scale,y=oy+s.player.y*scale;ctx.fillStyle='#ecf4b5';ctx.beginPath();ctx.arc(x,y,miniature?2.5:5,0,Math.PI*2);ctx.fill()}
function drawAtlas(ctx,s,w,h){ctx.fillStyle='#e5ead7';ctx.fillRect(0,0,w,h);const generation=atlasGeneration||F.generationOfMap(s.mapId),positions={forest:[.17,.15],highlands:[.50,.15],frost:[.83,.15],river:[.17,.50],campina:[.50,.50],coast:[.83,.50],marsh:[.17,.84],dunes:[.50,.84],crater:[.83,.84]},maps=Object.values(F.MAPS).filter(m=>F.generationOfMap(m.id)===generation),point=id=>{const m=F.MAPS[id],[x,y]=positions[F.districtBase(m.region)],offset={town:[0,-28],route:[-46,8],deep:[46,8],cave:[0,45],gym:[24,-28]}[m.id.split('-')[1]];return{x:x*w+offset[0],y:y*h+offset[1]}};ctx.strokeStyle='#a5b498';ctx.lineWidth=1;const seen=new Set();for(const m of maps)for(const id of m.links){if(F.generationOfMap(id)!==generation)continue;const key=[m.id,id].sort().join(':');if(seen.has(key))continue;seen.add(key);const a=point(m.id),b=point(id);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}for(const[id,c]of Object.entries(F.CITY).filter(([id])=>F.districtGeneration(id)===generation)){const[x,y]=positions[F.districtBase(id)];ctx.fillStyle='#385444';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(c.name,x*w,y*h-45);}for(const m of maps){const p=point(m.id),known=s.visitedMaps[m.id];ctx.fillStyle=known?F.REGIONS[m.region].color:'#c5cbbd';ctx.strokeStyle=s.mapId===m.id?'#1d4435':'#74896d';ctx.lineWidth=s.mapId===m.id?3:1;ctx.beginPath();ctx.arc(p.x,p.y,m.kind==='town'?9:6,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=known?'#294a36':'#7f8c76';ctx.font='9px sans-serif';ctx.textAlign='center';if(m.kind!=='town')ctx.fillText(m.kind==='gym'?'Gim.':m.kind==='cave'?'Cueva':m.id.endsWith('-deep')?'Ruta II':'Ruta I',p.x,p.y+18);}}
function renderJourney(){const s=api.state(),j=F.ensureGenerations(s),current=F.generationOfMap(s.mapId),g=F.GENERATIONS[current],p=F.generationProgress(s),known=Object.values(F.GENERATIONS).filter(g=>j.unlocked[g.id]!==undefined);$('atlasGeneration').innerHTML=known.map(g=>'<option value="'+g.id+'">'+g.name+'</option>').join('');$('atlasGeneration').value=String(atlasGeneration||current);$('generationJourney').innerHTML='<h3>'+g.name+'</h3><p>'+p.completed+' / '+p.total+' gimnasios completados. Sigue explorando: hay destinos que todavía no conoces.</p><div class="generation-cards">'+known.map(g=>{const progress=F.generationProgress(s,g.id);return'<article class="generation-card'+(g.id===current?' current':'')+'"><b>'+g.name+'</b><small>'+progress.completed+' / 9 medallas · '+(g.id===current?'Estás aquí':j.visited[g.id]?'Visitada':'Nueva frontera descubierta')+'</small><button class="secondary" data-generation-travel="'+g.id+'" '+(!F.canTravelGeneration(s,g.id)||!!api.battle()?'disabled':'')+'>Viajar</button></article>';}).join('')+'</div>';for(const button of document.querySelectorAll('[data-generation-travel]'))button.onclick=()=>{if(api.battle())return;if(F.travelGeneration(s,Number(button.dataset.generationTravel))){$('mapDialog').close();api.changed();api.toast('Llegaste a '+F.GENERATIONS[F.generationOfMap(s.mapId)].name);}};}
function renderMap(){const s=api.state(),m=F.MAPS[s.mapId];renderJourney();$('mapCanvas').innerHTML='';const canvas=document.createElement('canvas');canvas.width=660;canvas.height=mapMode==='local'?440:550;canvas.setAttribute('aria-label',mapMode==='local'?'Mapa local con niebla de exploración, salidas y tu posición.':'Atlas de 405 mapas en nueve regiones generacionales.');$('mapCanvas').append(canvas);const ctx=canvas.getContext('2d');if(mapMode==='local')drawLocal(ctx,s,canvas.width,canvas.height);else drawAtlas(ctx,s,canvas.width,canvas.height);$('mapPosition').textContent=m.name+' · '+(m.kind==='town'?'Zona segura':m.kind==='gym'?'Interior · '+F.gymProgress(s).completed+' / 3 duelos · ':m.kind==='cave'?'Cueva · ':'Ruta · ')+(m.kind==='town'?'':'niveles '+F.mapLevels(s).join('–'))+' · '+Math.floor(s.player.x/32)+', '+Math.floor(s.player.y/32);$('localMapTab').classList.toggle('selected',mapMode==='local');$('atlasMapTab').classList.toggle('selected',mapMode==='atlas');$('mapExits').innerHTML='<h3>Conexiones desde aquí</h3>'+F.worldExits(s).map(e=>'<span class="connectionchip'+(e.beginner?' beginner':'')+'">'+esc(e.label)+(e.beginner?'':F.MAPS[e.target].kind==='route'?' · Nv. '+F.mapLevels(s,e.target).join('–'):'')+'</span>').join('');$('regionList').innerHTML=Object.entries(F.CITY).filter(([id])=>F.districtGeneration(id)===(atlasGeneration||F.generationOfMap(s.mapId))).map(([id,original])=>{const c=F.cityInfo(s,id);return'<div class="regioncard"><span class="regionswatch" style="background:'+F.REGIONS[id].color+'"></span><div><b>'+c.name+'</b><small>'+F.REGIONS[id].name+' · '+(s.visitedMaps[id+'-town']?'Visitada':'Por descubrir')+'</small><p>Gimnasio '+F.TYPE[c.type][0]+' · '+c.leader+' · Nv. '+c.level+' · Medalla '+c.badge+(s.badges[id]?' ✓':'')+'</p><button class="secondary" data-travel="'+id+'-town" '+(m.kind!=='town'||!s.visitedMaps[id+'-town']||!!api.battle()||s.mapId===id+'-town'?'disabled':'')+'>Viajar</button></div></div>';}).join('');for(const button of document.querySelectorAll('[data-travel]'))button.onclick=()=>{if(api.battle()||F.MAPS[s.mapId].kind!=='town')return;if(F.travelTo(s,button.dataset.travel)){$('mapDialog').close();api.changed();api.toast('Llegaste a '+F.MAPS[s.mapId].name)}};return canvas}
function map(){atlasGeneration=F.generationOfMap(api.state().mapId);mapMode='local';const c=renderMap();api.openDialog('mapDialog');return c}
function mIsGym(s){return F.MAPS[s.mapId].kind==='gym'}
function drawMinimap(ctx){const s=api.state(),legendKey=JSON.stringify(s.shopping.cards)+JSON.stringify(s.legends?.records||{}),key=legendKey+':'+s.seed+':'+s.mapId+':'+Object.keys(s.fog[s.mapId]||{}).length+':'+JSON.stringify(s.field?.maps[s.mapId]||{})+':'+(mIsGym(s)?F.gymProgress(s).completed+':'+F.gymProgress(s).legacy:'');if(!mini||key!==miniKey){mini=document.createElement('canvas');mini.width=168;mini.height=124;drawLocal(mini.getContext('2d'),{...s,player:{x:1e6,y:1e6}},168,124,true);miniKey=key}ctx.save();ctx.globalAlpha=.86;ctx.drawImage(mini,780,54);ctx.restore();const b=F.MAPS[s.mapId].bounds,scale=Math.min(150/(b.right-b.left),106/(b.bottom-b.top));ctx.fillStyle='#eff5b9';ctx.beginPath();ctx.arc(864+s.player.x*scale,116+s.player.y*scale,2.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#193d2ddb';ctx.fillRect(780,178,168,20);ctx.fillStyle='#f0efd5';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('MAPA · '+(F.MAPS[s.mapId].kind==='town'?'CIUDAD':mIsGym(s)?'GIMNASIO · '+F.gymProgress(s).completed+'/3':F.mapLevels(s).join('–')),864,192)}
$('bagTarget').onchange=()=>{target=Number($('bagTarget').value);renderBag()};$('bagCategory').onchange=()=>{category=$('bagCategory').value;renderBag()};$('unequipBtn').onclick=()=>{if(F.equipHeld(api.state(),target,null,api.battle())){api.changed();renderBag()}};$('shopBuyTab').onclick=()=>{shopMode='buy';renderShop()};$('shopSellTab').onclick=()=>{shopMode='sell';renderShop()};$('atlasGeneration').onchange=()=>{const next=Number($('atlasGeneration').value);if(F.ensureGenerations(api.state()).unlocked[next]===undefined)return;atlasGeneration=next;mapMode='atlas';renderMap();};$('localMapTab').onclick=()=>{mapMode='local';renderMap()};$('atlasMapTab').onclick=()=>{mapMode='atlas';renderMap()};
return{bag,shop,map,renderBag,renderShop,drawMinimap};
};
